/**
 * @name Server-Side Request Forgery (SSRF) in urllib3
 * @description User-controlled input flowing to HTTP request functions could lead to SSRF
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf-urllib3
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // urllib3.request() or similar HTTP request methods
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("urllib3").getMember("request").getACall() and
      sink = call.getArg(0)  // URL parameter
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("urllib3").getMember(["HTTPConnection", "HTTPSConnection"]).getACall() and
      sink = call.getArg(0)  // host parameter
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("urllib3").getMember("PoolManager").getMember(["request", "urlopen"]).getACall() and
      sink = call.getArg(0)  // URL parameter
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability: user input $@ flows to HTTP request URL.", source.getNode(), "user input"
